def two_sum_sorted(sorted_lst, target):    # O(n) -- two pointers
    lo, hi = 0, len(sorted_lst) - 1
    while lo < hi:
        s = sorted_lst[lo] + sorted_lst[hi]
        if s == target:
            return (lo, hi)
        elif s < target:
            lo += 1          # need a bigger sum -> move left pointer up
        else:
            hi -= 1          # need a smaller sum -> move right pointer down
    return None

nums = [2, 4, 7, 11, 15, 20]
print(two_sum_sorted(nums, 18))   # finds 7 + 11 = 18 -> (2, 3)

class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def bst_insert(root, value):
    if root is None:
        return TreeNode(value)
    if value < root.value:
        root.left = bst_insert(root.left, value)
    else:
        root.right = bst_insert(root.right, value)
    return root

def bst_search(root, target):     # O(log n) average on a balanced BST
    if root is None:
        return False
    if root.value == target:
        return True
    elif target < root.value:
        return bst_search(root.left, target)
    else:
        return bst_search(root.right, target)

root = None
for v in [50, 30, 70, 20, 40, 60, 80]:
    root = bst_insert(root, v)

print(bst_search(root, 40))   # True
print(bst_search(root, 99))   # False

from collections import deque

# Adjacency list: a common, memory-efficient graph representation
graph = {
    "A": ["B", "C"],
    "B": ["A", "D"],
    "C": ["A", "D"],
    "D": ["B", "C", "E"],
    "E": ["D"],
}

def bfs(graph, start):
    visited = {start}
    queue = deque([start])
    order = []
    while queue:
        node = queue.popleft()
        order.append(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return order

print(bfs(graph, "A"))   # ['A', 'B', 'C', 'D', 'E'] -- explores level by level

def dfs(graph, start, visited=None, order=None):
    if visited is None:
        visited = set()
        order = []
    visited.add(start)
    order.append(start)
    for neighbor in graph[start]:
        if neighbor not in visited:
            dfs(graph, neighbor, visited, order)
    return order

print(dfs(graph, "A"))   # ['A', 'B', 'D', 'C', 'E'] -- commits deep before backtracking

