import functools

@functools.lru_cache(maxsize=None)   # a built-in, real memoization decorator
def fib_lru(n):
    if n <= 1:
        return n
    return fib_lru(n - 1) + fib_lru(n - 2)

print("fib_lru(80) =", fib_lru(80))    # instant, despite the naive version being hopeless here

def climb_stairs(n):          # tabulation -- O(n) time, O(1) space
    if n <= 2:
        return n
    prev2, prev1 = 1, 2        # ways to reach step 1, step 2
    for step in range(3, n + 1):
        prev2, prev1 = prev1, prev1 + prev2
    return prev1

for n in [1, 2, 3, 4, 5, 10]:
    print(f"climb_stairs({n}) = {climb_stairs(n)}")

def coin_change(coins, amount):    # tabulation -- minimum coins to make amount
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0                       # base case: 0 coins needed for amount 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                dp[a] = min(dp[a], dp[a - c] + 1)
    return dp[amount] if dp[amount] != float('inf') else -1

print(coin_change([1, 5, 10, 25], 63))   # 6: 25+25+10+1+1+1
print(coin_change([2], 3))                # -1: impossible with only 2s

