import hashlib

def h(key):
    return int(hashlib.sha256(str(key).encode()).hexdigest(), 16)

def naive_route(key, servers):          # NOT consistent hashing, despite the name similarity
    return servers[h(key) % len(servers)]

class ConsistentHashRing:                # a real ring: each server owns many points on it
    def __init__(self, servers, virtual_nodes=100):
        self.ring = {}
        self.virtual_nodes = virtual_nodes
        for s in servers:
            self.add_server(s)

    def add_server(self, server):
        for i in range(self.virtual_nodes):
            self.ring[h(f"{server}-{i}")] = server

    def get_server(self, key):
        target = h(key)
        for pos in sorted(self.ring.keys()):    # next server clockwise from the key
            if pos >= target:
                return self.ring[pos]
        return self.ring[min(self.ring)]          # wrap around the ring

keys = [f"user-{i}" for i in range(1000)]
servers = ["server-A", "server-B", "server-C"]

before_naive = {k: naive_route(k, servers) for k in keys}
after_naive = {k: naive_route(k, servers + ["server-D"]) for k in keys}
naive_remapped = sum(1 for k in keys if before_naive[k] != after_naive[k])

ring = ConsistentHashRing(servers)
before_ch = {k: ring.get_server(k) for k in keys}
ring.add_server("server-D")
after_ch = {k: ring.get_server(k) for k in keys}
ch_remapped = sum(1 for k in keys if before_ch[k] != after_ch[k])

print(f"naive hash%n:        adding 1 server remapped {naive_remapped}/1000 keys ({naive_remapped/10:.0f}%)")
print(f"consistent hashing:  adding 1 server remapped {ch_remapped}/1000 keys ({ch_remapped/10:.0f}%)")
